        pm.expect(pm.response.status).to.be.eql("Precondition Failed");
        try {
            if (responseData !== null && responseData !== undefined) {
        pm.test('Response has the `code` field',function(){
            try {
                const jsonResponse = pm.response.json();
                if (jsonResponse && pm.expect(jsonResponse).to.have.nested.property(`code`)) {
                    const value = ld.get(jsonResponse, `code`, null);
                    if (value !== null && value !== undefined) {
                        pm.expect(typeof value).to.equal("string");
                    }
                }
            } catch (error) {
                console.log("Error checking string field code:", error.message);
            }
        })

        pm.test(`code length to be atmost '3'`,function(){
            try {
                const value = ld.get(responseData, `code`, null);
                if (value !== null && value !== undefined && typeof value === 'string') {
                    pm.expect(value.length).to.be.at.most(3);
                }
            } catch (error) {
                console.log("Error checking maxLength for code:", error.message);
            }
        })

        pm.test('Response has the `message` field',function(){
            try {
                const jsonResponse = pm.response.json();
                if (jsonResponse && pm.expect(jsonResponse).to.have.nested.property(`message`)) {
                    const value = ld.get(jsonResponse, `message`, null);
                    if (value !== null && value !== undefined) {
                        pm.expect(typeof value).to.equal("string");
                    }
                }
            } catch (error) {
                console.log("Error checking string field message:", error.message);
            }
        })

        pm.test(`message length to be atmost '250'`,function(){
            try {
                const value = ld.get(responseData, `message`, null);
                if (value !== null && value !== undefined && typeof value === 'string') {
                    pm.expect(value.length).to.be.at.most(250);
                }
            } catch (error) {
                console.log("Error checking maxLength for message:", error.message);
            }
        })

        pm.test('Response has the `type` field',function(){
            try {
                const jsonResponse = pm.response.json();
                if (jsonResponse && pm.expect(jsonResponse).to.have.nested.property(`type`)) {
                    const value = ld.get(jsonResponse, `type`, null);
                    if (value !== null && value !== undefined) {
                        pm.expect(typeof value).to.equal("string");
                    }
                }
            } catch (error) {
                console.log("Error checking string field type:", error.message);
            }
        })

        pm.test(`type to be one of enum`, function(){ 
            try {
                const value = ld.get(responseData, `type`, null);
                if (value !== null && value !== undefined) {
                    pm.expect(["S","T","E"]).to.include(value);
                }
            } catch (error) {
                console.log("Error checking enum for type:", error.message);
            }
        })

        pm.test(`type length to be atmost '1'`,function(){
            try {
                const value = ld.get(responseData, `type`, null);
                if (value !== null && value !== undefined && typeof value === 'string') {
                    pm.expect(value.length).to.be.at.most(1);
                }
            } catch (error) {
                console.log("Error checking maxLength for type:", error.message);
            }
        })

            }
        } catch (error) {
            console.error('Error during response validation:', error.message);
        }
    });

}

